/**
 * PrintGuard AI - Sliced G-Code Parser
 * 
 * Parses real 3D printer G-code (generated by PrusaSlicer, Slic3r, Cura, etc.)
 * into structured layers, toolpaths, feature types, and slicing statistics.
 * 
 * Extracts:
 * - Layer boundaries and Z heights (;LAYER_CHANGE, ;Z:..., or Z coordinate moves)
 * - Movement classification: Extrusion moves (G1 with positive delta E) vs Travel moves (G0/G1 without E)
 * - Feature categorization based on slicer comments (;TYPE:...)
 * - Slicing statistics: estimated print time, filament used (mm/cm3/g), layer count, bed shape
 * - Bounding box (min/max X, Y, Z, dimensions, center)
 * - Typed arrays (Float32Array) for high-performance WebGL / Three.js rendering
 */

// Toolpath colour mapping (RGB 0.0 - 1.0)
export const TOOLPATH_COLORS = {
    external_perimeter: { hex: '#f97316', rgb: [0.976, 0.451, 0.086], label: 'Outer Wall' },
    perimeter:          { hex: '#10b981', rgb: [0.063, 0.725, 0.506], label: 'Inner Wall' },
    infill:             { hex: '#eab308', rgb: [0.918, 0.702, 0.031], label: 'Sparse Infill' },
    solid_infill:       { hex: '#3b82f6', rgb: [0.231, 0.510, 0.965], label: 'Solid Infill' },
    top_solid_infill:   { hex: '#38bdf8', rgb: [0.220, 0.741, 0.973], label: 'Top Surface' },
    bridge:             { hex: '#8b5cf6', rgb: [0.545, 0.361, 0.965], label: 'Bridge Infill' },
    support:            { hex: '#ec4899', rgb: [0.925, 0.282, 0.600], label: 'Support Material' },
    skirt:              { hex: '#84cc16', rgb: [0.518, 0.800, 0.086], label: 'Skirt / Brim' },
    custom:             { hex: '#94a3b8', rgb: [0.580, 0.639, 0.722], label: 'Custom G-code' },
    extrusion:          { hex: '#06b6d4', rgb: [0.024, 0.714, 0.831], label: 'Extrusion' },
    travel:             { hex: '#64748b', rgb: [0.392, 0.455, 0.545], label: 'Travel Move' },
};

export function mapCommentToFeatureType(comment) {
    const lower = comment.toLowerCase();
    if (lower.includes('external perimeter') || lower.includes('outer wall')) return 'external_perimeter';
    if (lower.includes('perimeter') || lower.includes('wall') || lower.includes('inner wall')) return 'perimeter';
    if (lower.includes('top solid infill') || lower.includes('top surface') || lower.includes('skin')) return 'top_solid_infill';
    if (lower.includes('solid infill')) return 'solid_infill';
    if (lower.includes('bridge')) return 'bridge';
    if (lower.includes('internal infill') || lower.includes('infill')) return 'infill';
    if (lower.includes('support')) return 'support';
    if (lower.includes('skirt') || lower.includes('brim')) return 'skirt';
    if (lower.includes('custom')) return 'custom';
    return 'extrusion';
}

/**
 * Parse raw G-code text string into structured preview model
 * @param {string} gcodeText - Raw G-code text
 * @param {Object} options - { onProgress: (pct) => void, bedCenter: {x, y} }
 * @returns {Object} Parsed G-code model
 */
export function parseGCode(gcodeText, options = {}) {
    if (!gcodeText || typeof gcodeText !== 'string') {
        throw new Error('G-code content is empty or invalid.');
    }

    if (gcodeText.length < 50) {
        throw new Error('G-code file is too small or incomplete.');
    }

    const lines = gcodeText.split(/\r?\n/);
    const totalLines = lines.length;

    // Header & metadata accumulators
    let slicer = null;
    let estimatedTimeStr = null;
    let estimatedFirstLayerTimeStr = null;
    let filamentUsedMm = null;
    let filamentUsedCm3 = null;
    let filamentUsedG = null;
    let bedShape = null;
    let nozzleTemp = null;
    let bedTemp = null;

    // State machine for toolhead movements
    let currentX = 0;
    let currentY = 0;
    let currentZ = 0;
    let currentE = 0;
    let prevE = 0;
    let isRelative = false; // G90 = absolute, G91 = relative
    let isRelativeE = false; // M82 = absolute E, M83 = relative E
    let currentType = 'extrusion';
    let currentLayerZ = 0;
    let currentLayerHeight = 0.2;

    // Bounding box tracking
    let minX = Infinity, maxX = -Infinity;
    let minY = Infinity, maxY = -Infinity;
    let minZ = Infinity, maxZ = -Infinity;
    let hasMovements = false;

    // Layer tracking
    const rawLayers = []; // temporary array of layer builder objects
    let currentLayer = null;

    function getOrCreateLayer(z, height = 0.2) {
        if (!currentLayer || Math.abs(currentLayer.z - z) > 0.001) {
            currentLayer = {
                layerIndex: rawLayers.length,
                z: Number(z.toFixed(3)),
                height: Number((height || 0.2).toFixed(3)),
                extrusions: [], // array of { p1, p2, type }
                travels: [],    // array of { p1, p2 }
                typesPresent: new Set()
            };
            rawLayers.push(currentLayer);
        }
        return currentLayer;
    }

    // Line scanner
    for (let i = 0; i < totalLines; i++) {
        const rawLine = lines[i];
        const trimmed = rawLine.trim();
        if (!trimmed) continue;

        // Extract metadata from comments
        if (trimmed.startsWith(';')) {
            const comment = trimmed.substring(1).trim();

            if (!slicer && comment.toLowerCase().startsWith('generated by')) {
                slicer = comment;
            } else if (comment.includes('estimated printing time (normal mode) =')) {
                estimatedTimeStr = comment.split('=')[1]?.trim();
            } else if (comment.includes('estimated first layer printing time')) {
                estimatedFirstLayerTimeStr = comment.split('=')[1]?.trim();
            } else if (comment.includes('filament used [mm] =')) {
                filamentUsedMm = parseFloat(comment.split('=')[1]);
            } else if (comment.includes('filament used [cm3] =')) {
                filamentUsedCm3 = parseFloat(comment.split('=')[1]);
            } else if (comment.includes('total filament used [g] =')) {
                filamentUsedG = parseFloat(comment.split('=')[1]);
            } else if (comment.startsWith('bed_shape =')) {
                bedShape = comment.split('=')[1]?.trim();
            } else if (comment.startsWith('temperature =')) {
                nozzleTemp = parseInt(comment.split('=')[1]);
            } else if (comment.startsWith('bed_temperature =')) {
                bedTemp = parseInt(comment.split('=')[1]);
            } else if (comment.startsWith('TYPE:')) {
                const typeName = comment.substring(5).trim();
                currentType = mapCommentToFeatureType(typeName);
            } else if (comment.startsWith('Z:')) {
                const zVal = parseFloat(comment.substring(2));
                if (!isNaN(zVal)) {
                    currentLayerZ = zVal;
                    currentZ = zVal;
                }
            } else if (comment.startsWith('HEIGHT:')) {
                const hVal = parseFloat(comment.substring(7));
                if (!isNaN(hVal)) {
                    currentLayerHeight = hVal;
                }
            } else if (comment === 'LAYER_CHANGE') {
                // Slicer marks an explicit layer change
            }
            continue;
        }

        // Parse G-code commands with possible inline comments
        const commentIdx = trimmed.indexOf(';');
        const codePart = commentIdx !== -1 ? trimmed.substring(0, commentIdx).trim() : trimmed;
        const inlineComment = commentIdx !== -1 ? trimmed.substring(commentIdx + 1).trim() : '';

        if (inlineComment.startsWith('TYPE:')) {
            currentType = mapCommentToFeatureType(inlineComment.substring(5).trim());
        }

        if (!codePart) continue;

        const tokens = codePart.split(/\s+/);
        const cmd = tokens[0].toUpperCase();

        if (cmd === 'G90') {
            isRelative = false;
        } else if (cmd === 'G91') {
            isRelative = true;
        } else if (cmd === 'M82') {
            isRelativeE = false;
        } else if (cmd === 'M83') {
            isRelativeE = true;
        } else if (cmd === 'G92') {
            // Coordinate reset (e.g. G92 E0)
            for (let t = 1; t < tokens.length; t++) {
                const tok = tokens[t];
                const axis = tok[0].toUpperCase();
                const val = parseFloat(tok.substring(1));
                if (axis === 'E' && !isNaN(val)) {
                    currentE = val;
                    prevE = val;
                } else if (axis === 'X' && !isNaN(val)) {
                    currentX = val;
                } else if (axis === 'Y' && !isNaN(val)) {
                    currentY = val;
                } else if (axis === 'Z' && !isNaN(val)) {
                    currentZ = val;
                }
            }
        } else if (cmd === 'M104' || cmd === 'M109') {
            // Temperature commands
            for (let t = 1; t < tokens.length; t++) {
                if (tokens[t].toUpperCase().startsWith('S')) {
                    const temp = parseFloat(tokens[t].substring(1));
                    if (!isNaN(temp) && !nozzleTemp) nozzleTemp = temp;
                }
            }
        } else if (cmd === 'M140' || cmd === 'M190') {
            // Bed temperature commands
            for (let t = 1; t < tokens.length; t++) {
                if (tokens[t].toUpperCase().startsWith('S')) {
                    const temp = parseFloat(tokens[t].substring(1));
                    if (!isNaN(temp) && !bedTemp) bedTemp = temp;
                }
            }
        } else if (cmd === 'G0' || cmd === 'G1' || cmd === 'G2' || cmd === 'G3') {
            let targetX = currentX;
            let targetY = currentY;
            let targetZ = currentZ;
            let targetE = currentE;
            let hasX = false, hasY = false, hasZ = false, hasE = false;

            for (let t = 1; t < tokens.length; t++) {
                const tok = tokens[t];
                if (!tok) continue;
                const axis = tok[0].toUpperCase();
                const val = parseFloat(tok.substring(1));
                if (isNaN(val)) continue;

                if (axis === 'X') {
                    targetX = isRelative ? currentX + val : val;
                    hasX = true;
                } else if (axis === 'Y') {
                    targetY = isRelative ? currentY + val : val;
                    hasY = true;
                } else if (axis === 'Z') {
                    targetZ = isRelative ? currentZ + val : val;
                    hasZ = true;
                } else if (axis === 'E') {
                    targetE = (isRelativeE || isRelative) ? currentE + val : val;
                    hasE = true;
                }
            }

            const deltaE = hasE ? targetE - prevE : 0;
            const movedSpatial = (targetX !== currentX) || (targetY !== currentY) || (targetZ !== currentZ);

            if (movedSpatial) {
                hasMovements = true;
                const isExtrusion = hasE && deltaE > 0.00001;

                // Update bounding box for extrusion moves
                if (isExtrusion) {
                    minX = Math.min(minX, currentX, targetX);
                    maxX = Math.max(maxX, currentX, targetX);
                    minY = Math.min(minY, currentY, targetY);
                    maxY = Math.max(maxY, currentY, targetY);
                    minZ = Math.min(minZ, currentZ, targetZ);
                    maxZ = Math.max(maxZ, currentZ, targetZ);
                }

                // Associate move with current layer
                const effectiveZ = targetZ > 0 ? targetZ : currentLayerZ;
                const layer = getOrCreateLayer(effectiveZ, currentLayerHeight);

                const p1 = [currentX, currentY, currentZ];
                const p2 = [targetX, targetY, targetZ];

                if (isExtrusion) {
                    const typeKey = currentType || 'extrusion';
                    layer.extrusions.push({ p1, p2, type: typeKey });
                    layer.typesPresent.add(typeKey);
                } else {
                    layer.travels.push({ p1, p2 });
                }
            }

            currentX = targetX;
            currentY = targetY;
            currentZ = targetZ;
            if (hasE) {
                currentE = targetE;
                prevE = targetE;
            }
        }
    }

    if (!hasMovements || rawLayers.length === 0) {
        throw new Error('Malformed G-code: No valid toolpath movements (G0/G1) or layers detected.');
    }

    // Filter out initial initialization layers before first extrusion
    let firstExtrusionSeen = false;
    const printingLayers = [];
    for (const raw of rawLayers) {
        if (raw.extrusions.length > 0) {
            firstExtrusionSeen = true;
        }
        if (firstExtrusionSeen && (raw.extrusions.length > 0 || raw.travels.length > 0)) {
            printingLayers.push(raw);
        }
    }

    const validLayers = printingLayers.length > 0 ? printingLayers : rawLayers.filter(l => l.extrusions.length > 0 || l.travels.length > 0);
    if (validLayers.length === 0) {
        throw new Error('Malformed G-code: File contains no extruded toolpaths.');
    }

    // If bounding box was not established from extrusions, fallback
    if (!isFinite(minX)) {
        minX = 0; maxX = 200; minY = 0; maxY = 200; minZ = 0; maxZ = 20;
    }

    const sizeX = maxX - minX;
    const sizeY = maxY - minY;
    const sizeZ = maxZ - minZ;
    const centerX = (minX + maxX) / 2;
    const centerY = (minY + maxY) / 2;
    const centerZ = (minZ + maxZ) / 2;

    // Convert raw layers into compact Float32Array geometries for high-performance rendering
    // Printer coordinate mapping to Three.js:
    // Three.js X = printer X - centerX
    // Three.js Y = printer Z (up)
    // Three.js Z = printer Y - centerY
    const layers = validLayers.map((raw, idx) => {
        const extCount = raw.extrusions.length;
        const travCount = raw.travels.length;

        // Extrusions: 2 vertices per segment, 3 floats per vertex (X, Y, Z)
        const extPositions = new Float32Array(extCount * 6);
        const extColors = new Float32Array(extCount * 6);

        let totalExtLength = 0;

        for (let s = 0; s < extCount; s++) {
            const seg = raw.extrusions[s];
            const p1 = seg.p1;
            const p2 = seg.p2;

            const colorDef = TOOLPATH_COLORS[seg.type] || TOOLPATH_COLORS.extrusion;
            const rgb = colorDef.rgb;

            const baseIdx = s * 6;
            // Vertex 1
            extPositions[baseIdx]     = p1[0] - centerX;
            extPositions[baseIdx + 1] = p1[2]; // Z is up in Three.js
            extPositions[baseIdx + 2] = p1[1] - centerY;

            // Vertex 2
            extPositions[baseIdx + 3] = p2[0] - centerX;
            extPositions[baseIdx + 4] = p2[2];
            extPositions[baseIdx + 5] = p2[1] - centerY;

            // Colors for both vertices
            extColors[baseIdx]     = rgb[0];
            extColors[baseIdx + 1] = rgb[1];
            extColors[baseIdx + 2] = rgb[2];
            extColors[baseIdx + 3] = rgb[0];
            extColors[baseIdx + 4] = rgb[1];
            extColors[baseIdx + 5] = rgb[2];

            const dx = p2[0] - p1[0];
            const dy = p2[1] - p1[1];
            const dz = p2[2] - p1[2];
            totalExtLength += Math.sqrt(dx * dx + dy * dy + dz * dz);
        }

        // Travels: 2 vertices per segment
        const travPositions = new Float32Array(travCount * 6);
        for (let s = 0; s < travCount; s++) {
            const seg = raw.travels[s];
            const p1 = seg.p1;
            const p2 = seg.p2;
            const baseIdx = s * 6;

            travPositions[baseIdx]     = p1[0] - centerX;
            travPositions[baseIdx + 1] = p1[2];
            travPositions[baseIdx + 2] = p1[1] - centerY;

            travPositions[baseIdx + 3] = p2[0] - centerX;
            travPositions[baseIdx + 4] = p2[2];
            travPositions[baseIdx + 5] = p2[1] - centerY;
        }

        return {
            layerIndex: idx, // 0-indexed internally
            layerNumber: idx + 1, // 1-indexed for UI display
            z: raw.z,
            height: raw.height,
            extCount,
            travCount,
            totalExtLengthMm: Number(totalExtLength.toFixed(1)),
            typesPresent: Array.from(raw.typesPresent),
            extPositions,
            extColors,
            travPositions
        };
    });

    // Extract all unique feature types present in the entire model
    const allFeatureTypes = new Set();
    layers.forEach(l => l.typesPresent.forEach(t => allFeatureTypes.add(t)));

    return {
        slicer: slicer || 'PrusaSlicer (Native Slicing Engine)',
        totalLayers: layers.length,
        layers,
        stats: {
            estimatedPrintTime: estimatedTimeStr || calculateEstimatedTime(layers),
            estimatedFirstLayerTime: estimatedFirstLayerTimeStr,
            filamentUsedMm: filamentUsedMm !== null ? Number(filamentUsedMm.toFixed(1)) : null,
            filamentUsedCm3: filamentUsedCm3 !== null ? Number(filamentUsedCm3.toFixed(2)) : null,
            filamentUsedG: filamentUsedG !== null ? Number(filamentUsedG.toFixed(1)) : null,
            nozzleTemp: nozzleTemp || 200,
            bedTemp: bedTemp || 60,
            bedShape: bedShape || '200x200 mm',
        },
        bounds: {
            minX: Number(minX.toFixed(2)),
            maxX: Number(maxX.toFixed(2)),
            minY: Number(minY.toFixed(2)),
            maxY: Number(maxY.toFixed(2)),
            minZ: Number(minZ.toFixed(2)),
            maxZ: Number(maxZ.toFixed(2)),
            sizeX: Number(sizeX.toFixed(2)),
            sizeY: Number(sizeY.toFixed(2)),
            sizeZ: Number(sizeZ.toFixed(2)),
            centerX: Number(centerX.toFixed(2)),
            centerY: Number(centerY.toFixed(2)),
            centerZ: Number(centerZ.toFixed(2)),
        },
        featureTypes: Array.from(allFeatureTypes).map(typeKey => ({
            key: typeKey,
            label: TOOLPATH_COLORS[typeKey]?.label || typeKey,
            hex: TOOLPATH_COLORS[typeKey]?.hex || '#06b6d4'
        }))
    };
}

/**
 * Fallback time calculation if slicer comments were stripped
 */
function calculateEstimatedTime(layers) {
    let totalMm = 0;
    layers.forEach(l => { totalMm += l.totalExtLengthMm; });
    const seconds = Math.round(totalMm / 45) + (layers.length * 2);
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}m ${secs}s`;
}
